-- rowfence 0.1.0-dev: definer_search_path. Generated by rowfence migrate from the policy; don't edit it,
-- change the policy and write the next migration.
-- the same policy; what rowfence makes of it changed

SELECT pg_catalog.set_config('lock_timeout', '10s', true) WHERE pg_catalog.current_setting('lock_timeout') IN ('0', '0ms');
SELECT pg_catalog.set_config('check_function_bodies', 'off', true);

-- this migration starts from the policy the previous one left
DO $authz_guard$
DECLARE v_lock text;
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_attribute
             WHERE attrelid = to_regclass('authz.policy_versions') AND attname = 'lock' AND NOT attisdropped) THEN
    EXECUTE 'SELECT lock FROM authz.policy_versions ORDER BY id DESC LIMIT 1' INTO v_lock;
  END IF;
  IF v_lock IS DISTINCT FROM 'e4630f7002dd43cf' THEN
    RAISE EXCEPTION 'rowfence: this migration changes the policy the migration before it left (%), but the database has % [AZ607]',
      'e4630f7002dd43cf', coalesce(v_lock, 'none')
      USING HINT = 'apply the migrations in order; a database changed with rowfence push or apply since needs the '
                   'migrations from the start (or rowfence apply of the policy the previous migration left)';
  END IF;
END $authz_guard$;

-- Functions below resolve names with the search_path in effect now: the schemas that exist, temporary schema last
DO $sp$
DECLARE v_path text; v_bad text; f record;
BEGIN
  SELECT pg_catalog.string_agg(pg_catalog.format('%I (%s)', pw.schema, pw.who), ', ') INTO v_bad FROM (SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, CURRENT_USER, 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_') pw;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'the search path has schemas that roles other than the owner may create objects in: % [AZ612]', v_bad
      USING HINT = 'rowfence''s functions that run as the owner resolve names on this path, so a function made there could run as the owner: revoke CREATE on those schemas, or apply with a search path without them';
  END IF;
  SELECT pg_catalog.string_agg(pg_catalog.quote_ident(s.name), ', ' ORDER BY s.i) INTO v_path
  FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) WITH ORDINALITY s(name, i)
  WHERE s.name::text !~ '^pg_temp_';
  PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ', v_path, 'pg_temp'), true);
  -- functions made before (a migration keeps those it doesn't change) take the same path
  FOR f IN SELECT p.oid::regprocedure AS fn FROM pg_catalog.pg_proc p
           WHERE p.pronamespace IN (SELECT n.oid FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int'))
             AND EXISTS (SELECT 1 FROM pg_catalog.unnest(p.proconfig) c
                         WHERE c ^@ 'search_path=' AND c <> 'search_path=pg_catalog, pg_temp'
                           AND c <> 'search_path=' || pg_catalog.current_setting('search_path')) LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path FROM CURRENT', f.fn);
  END LOOP;
END $sp$;

-- Check a permission from app code: SELECT authz.can('file', 11, 'edit')
-- (only objects that exist; plans are cached per session)
CREATE OR REPLACE FUNCTION authz.can(p_type text, p_id text, p_perm text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE v_allowed boolean; v_bigint bigint; v_uuid uuid;
BEGIN
  IF current_setting('authz_debug.log_decisions', true) = 'on'
     AND current_setting('authz_debug.logging', true) IS DISTINCT FROM 'on' THEN
    -- decision log (SET authz_debug.log_decisions = on; lines go to the server log)
    PERFORM set_config('authz_debug.logging', 'on', true);
    v_allowed := authz.can(p_type, p_id, p_perm);
    PERFORM set_config('authz_debug.logging', 'off', true);
    RAISE LOG 'authz decision: user=% type=% id=% perm=% -> %',
      coalesce(to_json(nullif(current_setting('authz.user_id', true), ''))::text, 'none'), to_json(p_type)::text,
      to_json(p_id)::text, to_json(p_perm)::text, coalesce(v_allowed::text, 'error');
    RETURN v_allowed;
  END IF;
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN false; END IF;
  CASE p_type
    WHEN 'group' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'manage' THEN RETURN coalesce((SELECT (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."group__admin" v WHERE v.id = o."id")
    OR authz_gen."group__manage__has"(o."parent_id")) FROM "fm"."groups" o WHERE o."id" = v_uuid), false);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowfence help AZ707';
      END CASE;
    WHEN 'membership' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'manage' THEN RETURN coalesce((SELECT authz_gen."group__manage__has"(o."group_id") FROM "fm"."group_members" o WHERE o."id" = v_bigint), false);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowfence help AZ707';
      END CASE;
    WHEN 'folder' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'share' THEN RETURN coalesce((SELECT (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (coalesce((inherit), false)
    AND authz_gen."folder__share__has"(o."parent_id"))) FROM "fm"."folders" o WHERE o."id" = v_bigint), false);
        WHEN 'edit' THEN RETURN coalesce((SELECT (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."folder__editor" v WHERE v.id = o."id")
    OR (coalesce((inherit), false)
    AND authz_gen."folder__edit__has"(o."parent_id"))) FROM "fm"."folders" o WHERE o."id" = v_bigint), false);
        WHEN 'view' THEN RETURN coalesce((SELECT (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."folder__editor" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__viewer" v WHERE v.id = o."id")
    OR (coalesce((inherit), false)
    AND authz_gen."folder__view__has"(o."parent_id"))) FROM "fm"."folders" o WHERE o."id" = v_bigint), false);
        WHEN 'break_glass' THEN RETURN coalesce((SELECT coalesce((exists (select 1 from fm.users u where u.id = (SELECT authz.uid()) and u.is_support)), false) FROM "fm"."folders" o WHERE o."id" = v_bigint), false);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowfence help AZ707';
      END CASE;
    WHEN 'file' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'share' THEN RETURN coalesce((SELECT (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR authz_gen."folder__share__has"(o."folder_id")) FROM "fm"."files" o WHERE o."id" = v_bigint), false);
        WHEN 'edit' THEN RETURN coalesce((SELECT (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."file__editor" v WHERE v.id = o."id")
    OR authz_gen."folder__edit__has"(o."folder_id")) FROM "fm"."files" o WHERE o."id" = v_bigint), false);
        WHEN 'view' THEN RETURN coalesce((SELECT (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."file__editor" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."file__viewer" v WHERE v.id = o."id")
    OR authz_gen."folder__view__has"(o."folder_id")) FROM "fm"."files" o WHERE o."id" = v_bigint), false);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowfence help AZ707';
      END CASE;
    WHEN 'version' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'view' THEN RETURN coalesce((SELECT EXISTS (SELECT 1 FROM authz_gen."file__view" v WHERE v.id = o."file_id") FROM "fm"."file_versions" o WHERE o."id" = v_bigint), false);
        WHEN 'edit' THEN RETURN coalesce((SELECT EXISTS (SELECT 1 FROM authz_gen."file__edit" v WHERE v.id = o."file_id") FROM "fm"."file_versions" o WHERE o."id" = v_bigint), false);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowfence help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowfence help AZ707';
  END CASE;
END $f$;

-- Everything the user holds a permission on: SELECT * FROM authz.list('folder', 'edit')
-- In pages, in key order: authz.list('file', 'view', NULL, 1000), then the last id seen as p_after
CREATE OR REPLACE FUNCTION authz.list(p_type text, p_perm text, p_after text DEFAULT NULL, p_limit int DEFAULT NULL)
RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN; END IF;
  CASE p_type || '.' || p_perm
    WHEN 'group.manage' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."groups" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."group__admin" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_gen."group__manage__direct" v WHERE v.id = o."parent_id")
    OR EXISTS (SELECT 1 FROM authz_gen."group__manage" v WHERE v.id = o."parent_id")));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."groups" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."group__admin" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_gen."group__manage__direct" v WHERE v.id = o."parent_id")
    OR EXISTS (SELECT 1 FROM authz_gen."group__manage" v WHERE v.id = o."parent_id")))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "fm"."groups" o
        WHERE o."id" > p_after::uuid AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."group__admin" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_gen."group__manage__direct" v WHERE v.id = o."parent_id")
    OR EXISTS (SELECT 1 FROM authz_gen."group__manage" v WHERE v.id = o."parent_id")))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'membership.manage' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."group_members" o
        WHERE (EXISTS (SELECT 1 FROM authz_gen."group__manage__direct" v WHERE v.id = o."group_id")
    OR EXISTS (SELECT 1 FROM authz_gen."group__manage" v WHERE v.id = o."group_id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."group_members" o
        WHERE (EXISTS (SELECT 1 FROM authz_gen."group__manage__direct" v WHERE v.id = o."group_id")
    OR EXISTS (SELECT 1 FROM authz_gen."group__manage" v WHERE v.id = o."group_id"))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "fm"."group_members" o
        WHERE o."id" > p_after::bigint AND (EXISTS (SELECT 1 FROM authz_gen."group__manage__direct" v WHERE v.id = o."group_id")
    OR EXISTS (SELECT 1 FROM authz_gen."group__manage" v WHERE v.id = o."group_id"))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'folder.share' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."folders" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (coalesce((inherit), false)
    AND (EXISTS (SELECT 1 FROM authz_gen."folder__share__direct" v WHERE v.id = o."parent_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__share" v WHERE v.id = o."parent_id"))));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."folders" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (coalesce((inherit), false)
    AND (EXISTS (SELECT 1 FROM authz_gen."folder__share__direct" v WHERE v.id = o."parent_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__share" v WHERE v.id = o."parent_id"))))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "fm"."folders" o
        WHERE o."id" > p_after::bigint AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (coalesce((inherit), false)
    AND (EXISTS (SELECT 1 FROM authz_gen."folder__share__direct" v WHERE v.id = o."parent_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__share" v WHERE v.id = o."parent_id"))))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'folder.edit' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."folders" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."folder__editor" v WHERE v.id = o."id")
    OR (coalesce((inherit), false)
    AND (EXISTS (SELECT 1 FROM authz_gen."folder__share__direct" v WHERE v.id = o."parent_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__edit" v WHERE v.id = o."parent_id"))));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."folders" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."folder__editor" v WHERE v.id = o."id")
    OR (coalesce((inherit), false)
    AND (EXISTS (SELECT 1 FROM authz_gen."folder__share__direct" v WHERE v.id = o."parent_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__edit" v WHERE v.id = o."parent_id"))))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "fm"."folders" o
        WHERE o."id" > p_after::bigint AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."folder__editor" v WHERE v.id = o."id")
    OR (coalesce((inherit), false)
    AND (EXISTS (SELECT 1 FROM authz_gen."folder__share__direct" v WHERE v.id = o."parent_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__edit" v WHERE v.id = o."parent_id"))))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'folder.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."folders" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."folder__editor" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__viewer" v WHERE v.id = o."id")
    OR (coalesce((inherit), false)
    AND (EXISTS (SELECT 1 FROM authz_gen."folder__share__direct" v WHERE v.id = o."parent_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__view" v WHERE v.id = o."parent_id"))));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."folders" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."folder__editor" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__viewer" v WHERE v.id = o."id")
    OR (coalesce((inherit), false)
    AND (EXISTS (SELECT 1 FROM authz_gen."folder__share__direct" v WHERE v.id = o."parent_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__view" v WHERE v.id = o."parent_id"))))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "fm"."folders" o
        WHERE o."id" > p_after::bigint AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."folder__editor" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__viewer" v WHERE v.id = o."id")
    OR (coalesce((inherit), false)
    AND (EXISTS (SELECT 1 FROM authz_gen."folder__share__direct" v WHERE v.id = o."parent_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__view" v WHERE v.id = o."parent_id"))))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'folder.break_glass' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."folders" o
        WHERE coalesce((exists (select 1 from fm.users u where u.id = (SELECT authz.uid()) and u.is_support)), false);
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."folders" o
        WHERE coalesce((exists (select 1 from fm.users u where u.id = (SELECT authz.uid()) and u.is_support)), false)
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "fm"."folders" o
        WHERE o."id" > p_after::bigint AND coalesce((exists (select 1 from fm.users u where u.id = (SELECT authz.uid()) and u.is_support)), false)
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'file.share' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."files" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (EXISTS (SELECT 1 FROM authz_gen."folder__share__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__share" v WHERE v.id = o."folder_id")));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."files" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (EXISTS (SELECT 1 FROM authz_gen."folder__share__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__share" v WHERE v.id = o."folder_id")))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "fm"."files" o
        WHERE o."id" > p_after::bigint AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (EXISTS (SELECT 1 FROM authz_gen."folder__share__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__share" v WHERE v.id = o."folder_id")))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'file.edit' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."files" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."file__editor" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_gen."folder__share__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__edit" v WHERE v.id = o."folder_id")));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."files" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."file__editor" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_gen."folder__share__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__edit" v WHERE v.id = o."folder_id")))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "fm"."files" o
        WHERE o."id" > p_after::bigint AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."file__editor" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_gen."folder__share__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__edit" v WHERE v.id = o."folder_id")))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'file.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."files" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."file__editor" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."file__viewer" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_gen."folder__share__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__view" v WHERE v.id = o."folder_id")));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."files" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."file__editor" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."file__viewer" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_gen."folder__share__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__view" v WHERE v.id = o."folder_id")))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "fm"."files" o
        WHERE o."id" > p_after::bigint AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."file__editor" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."file__viewer" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_gen."folder__share__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_gen."folder__view" v WHERE v.id = o."folder_id")))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'version.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."file_versions" o
        WHERE EXISTS (SELECT 1 FROM authz_gen."file__view" v WHERE v.id = o."file_id");
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."file_versions" o
        WHERE EXISTS (SELECT 1 FROM authz_gen."file__view" v WHERE v.id = o."file_id")
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "fm"."file_versions" o
        WHERE o."id" > p_after::bigint AND EXISTS (SELECT 1 FROM authz_gen."file__view" v WHERE v.id = o."file_id")
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'version.edit' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."file_versions" o
        WHERE EXISTS (SELECT 1 FROM authz_gen."file__edit" v WHERE v.id = o."file_id");
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."file_versions" o
        WHERE EXISTS (SELECT 1 FROM authz_gen."file__edit" v WHERE v.id = o."file_id")
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "fm"."file_versions" o
        WHERE o."id" > p_after::bigint AND EXISTS (SELECT 1 FROM authz_gen."file__edit" v WHERE v.id = o."file_id")
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    ELSE
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowfence help AZ707';
  END CASE;
END $f$;

-- Privileges the policy doesn't give on rowfence's schemas and what is in them are taken back
DO $r$
DECLARE g record; v_taken int := 0;
BEGIN
  FOR g IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = 'fm_app'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = 'fm_app'::regrole AND c.relnamespace = 'authz_gen'::regnamespace AND a.privilege_type = 'SELECT')
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, 'fm_app'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = 'fm_app'::regrole)
    AND NOT (p.pronamespace = 'authz'::regnamespace AND a.grantee = 'fm_app'::regrole AND p.oid = ANY (ARRAY['authz.uid()', 'authz.principal()', 'authz.ctx(text)', 'authz.link_hashes()', 'authz.act_as(text, text)', 'authz.connection_check()', 'authz.can(text, text, text)', 'authz.list(text, text, text, integer)', 'authz.perms(text, text)', 'authz.perms_of(text, text[])', 'authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.share(text, bigint, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.share(text, bigint, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, text, text)', 'authz.unshare(text, bigint, text, text, bigint, text)', 'authz.unshare(text, bigint, text, text, text, text)', 'authz.create_link(text, text, text, timestamptz)', 'authz.create_link(text, bigint, text, timestamptz)', 'authz.create_role(text, text, text, text, text[])', 'authz.create_role(text, bigint, text, text, text[])', 'authz.set_role_permissions(bigint, text[])', 'authz.delete_role(bigint)', 'authz.roles_of(text, text)', 'authz.who(text, text, text)', 'authz.explain(text, text, text, text)', 'authz.list_shares(text, text)', 'authz.explain_rule(text, text, text, jsonb)', 'authz.who_among(text, text, text, text[], text)', 'authz.create_api_key(text, text, timestamptz, text, text)', 'authz.list_api_keys(text, text)', 'authz.revoke_api_key(bigint)', 'authz.login_key(text)', 'authz.login_jwt(text)', 'authz.view_as(text, text)', 'authz.request_access(text, text, text, text, interval)', 'authz.request_access(text, bigint, text, text, interval)', 'authz.pending_requests()', 'authz.decide_request(bigint, boolean, text)', 'authz.cancel_request(bigint)', 'authz.break_glass(text, text, text, text, interval)', 'authz.start_review(text, text, timestamptz)', 'authz.review_items(bigint)', 'authz.review_decide(bigint, integer, boolean)', 'authz.close_review(bigint, boolean)', 'authz.who(text, bigint, text)', 'authz.explain(text, bigint, text, text)', 'authz.list_shares(text, bigint)', 'authz.who(text, uuid, text)', 'authz.explain(text, uuid, text, text)', 'authz.list_shares(text, uuid)', 'authz.can(text, bigint, text)', 'authz.can(text, uuid, text)', 'authz.who_among(text, bigint, text, text[], text)', 'authz.who_among(text, uuid, text, text[], text)', 'authz.perms(text, bigint)', 'authz.perms(text, uuid)']::regprocedure[])) LOOP
    EXECUTE g.stmt;
    v_taken := v_taken + 1;
  END LOOP;
  IF v_taken > 0 THEN
    RAISE WARNING 'took back % privileges on rowfence''s schemas that the policy doesn''t give (default privileges of the owner, or grants made since the last apply)', v_taken;
  END IF;
END $r$;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz FROM PUBLIC;

GRANT USAGE ON SCHEMA authz, authz_gen TO fm_app;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz_gen FROM PUBLIC;

-- the policy now in force
INSERT INTO authz.policy_versions (action, policy, files, version, lock)
VALUES ('apply', $authz_policy$-- policy.authz: who can do what in the file manager. Applied by db/migrate.py with authz.apply().
-- Folders nest; what you may do in a folder you may do in everything inside it, unless a folder
-- stops inheritance (inherit = false). People share folders and files with users and groups.

role fm_app

type user = fm.users (id uuid)

type group = fm.groups (id uuid)
  member : user         = fm.group_members(group_id -> user_id)
  member : group#member = fm.groups(parent_id -> id)          -- members of sub-groups count too
  owner  : user         = owner_id
  admin  : user         = fm.group_members(group_id -> user_id) where {is_admin}
  parent : group        = parent_id

  -- who may rename it, add and remove members and sub-groups: its owner, its admins, and those of the groups above
  can manage = owner or admin or parent.manage

type membership = fm.group_members
  group : group = group_id
  person : user = user_id

  can manage = group.manage

type folder = fm.folders
  parent : folder = parent_id
  owner  : user   = owner_id
  viewer : user, group#member, link shared by share
  editor : user, group#member       shared by share

  can share = owner or (parent.share and {inherit})
  can edit  = share or editor or (parent.edit and {inherit})
  can view  = edit or viewer or (parent.view and {inherit})
  -- support staff may give themselves access for a short time: audited, announced (authz.break_glass)
  can break_glass = {exists (select 1 from fm.users u where u.id = authz.uid() and u.is_support)}

type file = fm.files
  folder : folder = folder_id
  owner  : user   = owner_id
  viewer : user, group#member, link shared by share
  editor : user, group#member       shared by share

  can share = owner or folder.share
  can edit  = share or editor or folder.edit
  can view  = edit or viewer or folder.view

-- every stored object is a version of a file, with the file's permissions
type version = fm.file_versions
  file : file = file_id

  can view = file.view
  can edit = file.edit

rules fm.folders
  select                 : view
  insert                 : ({parent_id is null} or parent.edit) and {owner_id = authz.uid()}
  update                 : edit
  update parent_id after : parent.edit or ({parent_id is null} and share)
  update id, owner_id, inherit : share
  delete                 : share

rules fm.files
  select                 : view
  insert                 : folder.edit and {owner_id = authz.uid()} and {fm.key_is_new(object_key)}
  update                 : edit
  update folder_id after : folder.edit
  update id, owner_id    : share
  -- a file shows one of its own versions, never another file's object
  update object_key after : {object_key IN (SELECT v.object_key FROM fm.file_versions v WHERE v.file_id = files.id AND v.ready)}
  delete                 : edit

rules fm.file_versions
  select                 : view
  insert                 : file.edit and {created_by = authz.uid()}
  update                 : edit
  update id, file_id, object_key, created_by : {false}             -- what a version is never changes
  delete                 : edit

-- everyone signed in sees the groups and who is in them (to share with them)
rules fm.groups
  select                 : signed_in
  insert                 : {owner_id = authz.uid()} and ({parent_id is null} or parent.manage)
  update                 : manage
  update parent_id after : {parent_id is null} or parent.manage
  update id, owner_id    : manage
  delete                 : manage

rules fm.group_members
  select                 : signed_in
  insert                 : manage
  update                 : manage
  update group_id after  : manage
  delete                 : manage or person                    -- anyone may leave a group
$authz_policy$,
  $authz_files${}$authz_files$::jsonb, '0.1.0-dev+0fe5117c244e', '6790cf419f519993');
